def pre(moves):
    if len(moves) > 6:
        return False
    for m in moves:
        if m < -10 or m > 10:
            return False
    return True

def post(moves, result):
    bal = 0
    expected = False
    for m in moves:
        bal += m
        if bal < 0:
            expected = True
    return result == expected
